// RenderedFeatureQueryOptions corresponds to
// mln_rendered_feature_query_options. Options for rendered feature queries.
//
// See mln_rendered_feature_query_options in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/query_8h.html
type RenderedFeatureQueryOptions struct {
	// Optional style layer IDs. When absent, all rendered layers are queried.
	LayerIds []string
	// Optional UTF-8 MapLibre style-spec filter JSON. Null means no filter.
	Filter *[]byte
}

func copyRenderedFeatureQueryOptions(raw C.mln_rendered_feature_query_options) RenderedFeatureQueryOptions {
	var result RenderedFeatureQueryOptions
	if raw.fields&C.MLN_RENDERED_FEATURE_QUERY_OPTION_LAYER_IDS != 0 {
		result.LayerIds = func() []string {
			length := bindingLength(uint64(raw.layer_id_count))
			result := make([]string, length)
			for i := range result {
				item := *(*C.mln_buffer_view)(bindingElement(unsafe.Pointer(raw.layer_ids), i, uint64(unsafe.Sizeof(*raw.layer_ids)), unsafe.Sizeof(*raw.layer_ids), unsafe.Alignof(*raw.layer_ids)))
				result[i] = bindingString(item.data, uint64(item.size))
			}
			return result
		}()
	}
	result.Filter = func() *[]byte {
		if raw.filter == nil {
			return nil
		}
		value := bindingBytes((*raw.filter).data, uint64((*raw.filter).size))
		return &value
	}()
	return result
}

func nativeRenderedFeatureQueryOptions(input RenderedFeatureQueryOptions, arena *bindingArena) C.mln_rendered_feature_query_options {
	raw := C.mln_rendered_feature_query_options_default()
	raw.size = bindingCountLike(raw.size, int(unsafe.Sizeof(raw)))
	raw.fields = 0
	if input.LayerIds != nil {
		{
			raw.layer_ids = (*C.mln_buffer_view)(arena.array(len(input.LayerIds), unsafe.Sizeof(*raw.layer_ids)))
			items := unsafe.Slice(raw.layer_ids, len(input.LayerIds))
			raw.layer_id_count = bindingCountLike(raw.layer_id_count, len(input.LayerIds))
			for i, item := range input.LayerIds {
				items[i] = C.mln_buffer_view{data: arena.bytes([]byte(item)), size: C.size_t(len(item))}
			}
		}
		raw.fields |= C.MLN_RENDERED_FEATURE_QUERY_OPTION_LAYER_IDS
	}
	if input.Filter != nil {
		pointer := (*C.mln_buffer_view)(arena.allocate(unsafe.Sizeof(*raw.filter)))
		*pointer = C.mln_buffer_view{data: arena.bytes(*input.Filter), size: C.size_t(len(*input.Filter))}
		raw.filter = pointer
	}
	return raw
}

func DefaultRenderedFeatureQueryOptions() RenderedFeatureQueryOptions {
	return copyRenderedFeatureQueryOptions(C.mln_rendered_feature_query_options_default())
}

// RenderedQueryGeometry corresponds to mln_rendered_query_geometry. Rendered
// feature query geometry descriptor.
//
// See mln_rendered_query_geometry in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/query_8h.html
type RenderedQueryGeometry struct{ Data RenderedQueryGeometryData }

func copyRenderedQueryGeometry(raw C.mln_rendered_query_geometry) RenderedQueryGeometry {
	var result RenderedQueryGeometry
	result.Data = func() RenderedQueryGeometryData {
		switch raw._type {
		case C.MLN_RENDERED_QUERY_GEOMETRY_TYPE_POINT:
			return RenderedQueryGeometryDataPointVariant{Value: copyScreenPoint((*(*C.mln_screen_point)(unsafe.Pointer(&raw.data))))}
		case C.MLN_RENDERED_QUERY_GEOMETRY_TYPE_BOX:
			return RenderedQueryGeometryDataBoxVariant{Value: copyScreenBox((*(*C.mln_screen_box)(unsafe.Pointer(&raw.data))))}
		case C.MLN_RENDERED_QUERY_GEOMETRY_TYPE_LINE_STRING:
			return RenderedQueryGeometryDataLineStringVariant{Value: copyScreenLineString((*(*C.mln_screen_line_string)(unsafe.Pointer(&raw.data))))}
		}
		return UnknownVariant{Tag: uint32(raw._type)}
	}()
	return result
}

func nativeRenderedQueryGeometry(input RenderedQueryGeometry, arena *bindingArena) C.mln_rendered_query_geometry {
	raw := C.mln_rendered_query_geometry{}
	raw.size = bindingCountLike(raw.size, int(unsafe.Sizeof(raw)))
	if input.Data == nil {
		arena.fail("missing union variant")
	}
	raw._type = C.uint32_t(input.Data.bindingTag())
	switch variant := input.Data.(type) {
	case RenderedQueryGeometryDataPointVariant:
		*(*C.mln_screen_point)(unsafe.Pointer(&raw.data)) = nativeScreenPoint(variant.Value, arena)
	case RenderedQueryGeometryDataBoxVariant:
		*(*C.mln_screen_box)(unsafe.Pointer(&raw.data)) = nativeScreenBox(variant.Value, arena)
	case RenderedQueryGeometryDataLineStringVariant:
		*(*C.mln_screen_line_string)(unsafe.Pointer(&raw.data)) = nativeScreenLineString(variant.Value, arena)
	default:
		arena.fail("unknown input union variant")
	}
	return raw
}

